import { readFileSync, writeFileSync } from "node:fs";
const tokens = JSON.parse(
  readFileSync(
    new URL("../packages/design-tokens/happyhands.json", import.meta.url),
    "utf8",
  ),
);
const css =
  "@import url('/fonts/inter/index.css');\n/* Generated by scripts/brand-tokens.mjs. Source: shadcn b1VlItwO / radix-luma; user requested 2026-10-30. Extended status and brand tokens retained. */\n" +
  Object.entries(tokens)
    .map(
      ([mode, values]) =>
        `${mode === "light" ? ":root, " : ""}:root[data-hh-theme="${mode}"], :root[data-theme="${mode}"] {\n${Object.entries(
          values,
        )
          .map(([k, v]) => `  --hh-${k}: ${v};`)
          .join("\n")}\n}`,
    )
    .join("\n");
writeFileSync(
  new URL("../packages/design-tokens/happyhands.css", import.meta.url),
  css,
);

writeFileSync(new URL('../public/systems/happyhands/tokens.json', import.meta.url), JSON.stringify(tokens, null, 2) + '\n');
